import java.util.Arrays;

class PrimMST {

    private static final int INFINITY = Integer.MAX_VALUE;

    private int minKey(int[] key, boolean[] inMST)
    {
        int min = INFINITY, minIndex = -1;

        for (int vertex = 0; vertex < inMST.length; vertex++)
            if (!inMST[vertex] && key[vertex] < min) {
                min = key[vertex];
                minIndex = vertex;
            }

        return minIndex;
    }

    private void printMST(int[] parent, int[][] graph)
    {
        System.out.println("Edge \tWeight");
        int totalWeight = 0;
        for (int i = 1; i < graph.length; i++) {
            int weight = graph[parent[i]][i];
            System.out.println(parent[i] + " - " + i + "\t" + weight);
            totalWeight += weight;
        }
        System.out.println("Total weight: " + totalWeight);
    }

    void primMST(int[][] graph)
    {
        int vertexCount = graph.length;

        int[] parent = new int[vertexCount];
        int[] key = new int[vertexCount];
        boolean[] inMST = new boolean[vertexCount];

        Arrays.fill(key, INFINITY);
        key[0] = 0;
        parent[0] = -1;

        for (int count = 0; count < vertexCount - 1; count++) {
            int current = minKey(key, inMST);
            if (current == -1)
                break;

            inMST[current] = true;

            for (int neighbor = 0; neighbor < vertexCount; neighbor++)
                if (graph[current][neighbor] != 0 && !inMST[neighbor]
                    && graph[current][neighbor] < key[neighbor]) {
                    parent[neighbor] = current;
                    key[neighbor] = graph[current][neighbor];
                }
        }

        printMST(parent, graph);
    }

    public static void main(String[] args)
    {
        PrimMST t = new PrimMST();
        int[][] graph = { { 0, 2, 0, 6, 0 },
                          { 2, 0, 3, 8, 5 },
                          { 0, 3, 0, 0, 7 },
                          { 6, 8, 0, 0, 9 },
                          { 0, 5, 7, 9, 0 } };

        t.primMST(graph);
    }
}

